const { check, validationResult } = require('express-validator');
const createError = require('http-errors');
const morgan = require('morgan');
const timeout = require('express-timeout-handler');
const { cleanEnv, str, port } = require('envalid');

// Validate environment variables
const env = cleanEnv(process.env, {
  NODE_ENV: str({ default: 'development' }),
  PORT: port({ default: 3000 }),
  ALLOWED_ORIGINS: str({ default: '*' }),
});

const app = express();

// Security Middleware
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
      },
    },
    hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  })
);
app.use(cors({ origin: env.ALLOWED_ORIGINS.split(',') }));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
});
app.use(limiter);

// Request Timeout
const timeoutHandler = new timeout.Handler({ timeout: 5000 });
app.use(timeout.handler(timeoutHandler));

// Logging
app.use(morgan('dev'));

// Body Parsing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Input Validation Middleware
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return next(createError(400, { errors: errors.array() }));
    }
    next();
  };
};

// Routes
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: env.NODE_ENV,
  });
});

app.get('/users', validate([
  check('id').optional().isInt().withMessage('ID must be an integer')
]), (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    if (req.query.id) {
      const user = users.find(u => u.id === parseInt(req.query.id));
      if (!user) return next(createError(404, 'User not found'));
      return res.json(user);
    }

    res.json(users);
  } catch (err) {
    next(err);
  }
});

// 404 Handler
app.use((req, res, next) => {
  next(createError(404, 'Route not found'));
});

// Centralized Error Handler
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = env.NODE_ENV === 'production' && status === 500
    ? 'Internal Server Error'
    : err.message;

  res.status(status).json({
    error: {
      status,
      message,
      ...(env.NODE_ENV === 'development' && { stack: err.stack }),
    },
  });
});

// Start Server
app.listen(env.PORT, () => {
  console.log(`Server running on port ${env.PORT} in ${env.NODE_ENV} mode`);
});

module.exports = app;

