"""
Improved app.js with:
- Input validation via express-validator
- Centralized error handling
- Security middleware (Helmet, CORS, rate limiting)
- Logging (Morgan)
- Environment variables (dotenv)
- Async error handling
"""

require('dotenv').config();
require('express-async-errors');
const express = require('express');
const { query, validationResult } = require('express-validator');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const createError = require('http-errors');
const fs = require('fs');
const path = require('path');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: ['https://your-trusted-domain.com'], // Restrict in production
  methods: ['GET'], // Only allow GET requests
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
});
app.use(limiter);

// Logging
app.use(morgan('combined'));
const errorLogStream = fs.createWriteStream(path.join(__dirname, 'error.log'), { flags: 'a' });

// Input validation for `/users`
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be an integer between 1 and 100'),
  query('search').optional().escape(), // XSS protection
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Health check (unchanged)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 404 handler
app.use((req, res, next) => {
  next(createError(404, 'Not Found'));
});

// Centralized error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  errorLogStream.write(`${new Date().toISOString()} - ${err.stack}\n`);
  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
  });
});

// Start server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

module.exports = app;

